class TextEditor:
    """发起人类 - 文本编辑器"""
    
    def __init__(self):
        self._content = ""
    
    def write(self, text):
        """写入文本"""
        self._content += text
    
    def get_content(self):
        """获取当前内容"""
        return self._content
    
    def save(self):
        """创建备忘录 - 保存当前状态"""
        return TextEditorMemento(self._content)
    
    def restore(self, memento):
        """恢复状态 - 从备忘录读取"""
        self._content = memento.get_content()


class HistoryManager:
    """管理者类 - 历史记录管理器"""
    
    def __init__(self):
        self._mementos = []
    
    def push(self, memento):
        """保存备忘录"""
        self._mementos.append(memento)
    
    def pop(self):
        """获取最新的备忘录"""
        if self._mementos:
            return self._mementos.pop()
        return None

from abc import ABC, abstractmethod
from typing import List

# 观察者接口
class Observer(ABC):
    @abstractmethod
    def update(self, message: str):
        """观察者更新方法"""
        pass

# 主题接口
class Subject(ABC):
    @abstractmethod
    def register_observer(self, observer: Observer):
        """注册观察者"""
        pass
    
    @abstractmethod
    def remove_observer(self, observer: Observer):
        """移除观察者"""
        pass
    
    @abstractmethod
    def notify_observers(self):
        """通知所有观察者"""
        pass

# 具体主题 - 新闻发布器
class NewsPublisher(Subject):
    def __init__(self):
        self._observers: List[Observer] = []
        self._latest_news = ""
    
    def register_observer(self, observer: Observer):
        """注册观察者"""
        if observer not in self._observers:
            self._observers.append(observer)
            print(f"观察者 {observer.__class__.__name__} 注册成功")
    
    def remove_observer(self, observer: Observer):
        """移除观察者"""
        if observer in self._observers:
            self._observers.remove(observer)
            print(f"观察者 {observer.__class__.__name__} 移除成功")
    
    def notify_observers(self):
        """通知所有观察者"""
        print(f"\n发布新消息: {self._latest_news}")
        for observer in self._observers:
            observer.update(self._latest_news)
    
    def publish_news(self, news: str):
        """发布新闻"""
        self._latest_news = news
        self.notify_observers()
    
    def get_observer_count(self) -> int:
        """获取观察者数量"""
        return len(self._observers)

