from abc import ABC, abstractmethod

class AbstractClass(ABC):
    """模板方法模式的抽象基类"""
    
    def template_method(self):
        """模板方法 - 定义算法骨架"""
        self.step1()
        self.step2()
        self.hook()
        self.step3()
    
    @abstractmethod
    def step1(self):
        """抽象方法1 - 必须由子类实现"""
        pass
    
    @abstractmethod
    def step2(self):
        """抽象方法2 - 必须由子类实现"""
        pass
    
    def step3(self):
        """具体方法 - 已有默认实现"""
        print("执行步骤3 - 默认实现")
    
    def hook(self):
        """钩子方法 - 可选步骤，子类可选择重写"""
        print("执行钩子方法 - 默认什么都不做")

class Circle:
    def __init__(self, radius):
        self.radius = radius
    
    def area(self):
        return 3.14 * self.radius * self.radius
    
    def perimeter(self):
        return 2 * 3.14 * self.radius

class Rectangle:
    def __init__(self, width, height):
        self.width = width
        self.height = height
    
    def area(self):
        return self.width * self.height
    
    def perimeter(self):
        return 2 * (self.width + self.height)
